# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def student(last, first):
    return Student("1", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        students = [
            student("Halloway", "Juno"),
            student("Zed", "Ann"),
            student("Dunmere", "Piet")
        ]
        self.assertEqual(
            seating_rows(students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zed, Ann"
            ]
        )

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([student("A", "B")], seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
